1	diff --git a/javascripts/__tests__/notation.test.js b/javascripts/__tests__/notation.test.js
2	new file mode 100644
3	index 000000000..a1b2c3d4e
4	--- /dev/null
5	+++ b/javascripts/__tests__/notation.test.js
6	@@ -0,0 +1,214 @@
7	+import { describe, test, expect, vi, beforeAll, beforeEach } from 'vitest';
8	+import fs from 'fs';
9	+import path from 'path';
10	+import Vue from 'vue';
11	+import { compileToFunctions } from 'vue-template-compiler';
12	+
13	+const __dirname = path.dirname(new URL(import.meta.url).pathname);
14	+
15	+// Mock all direct imports of celestials.js before it runs
16	+const MockEffarig = { glyphLevelCap: 2000 };
17	+vi.mock('../core/celestials/effarig', () => ({ Effarig: MockEffarig }));
18	+vi.mock('../core/celestials/enslaved', () => ({ Enslaved: {} }));
19	+vi.mock('../core/celestials/laitela/laitela', () => ({ Laitela: {} }));
20	+vi.mock('../core/celestials/pelle/pelle', () => ({ Pelle: {} }));
21	+vi.mock('../core/celestials/ra/ra', () => ({ Ra: {} }));
22	+vi.mock('../core/celestials/teresa', () => ({ Teresa: {} }));
23	+vi.mock('../core/celestials/V', () => ({ V: {} }));
24	+
25	+beforeAll(() => {
26	+  // Set up the global GameDatabase that celestials.js writes to at module-level
27	+  global.GameDatabase = {
28	+    celestials: {
29	+      descriptions: {},
30	+      effarig: {},
31	+      alchemy: {},
32	+      pelle: {},
33	+      quotes: {}
34	+    }
35	+  };
36	+  // Stub formatInt as a SPY that produces a recognisable tagged output.
37	+  // Base (unfixed): raw interpolation gives plain numbers -> formatInt is
38	+  // never invoked, and no "[FMT:" marker appears.
39	+  // Fix: value passed through formatInt(...) -> "[FMT:<value>]", and the spy
40	+  // records the call. Asserting on the spy (not just the rendered text) rules
41	+  // out a "fix" that hardcodes the tagged string instead of calling formatInt.
42	+  global.formatInt = vi.fn((v) => `[FMT:${v}]`);
43	+});
44	+
45	+beforeEach(() => {
46	+  global.formatInt.mockClear();
47	+});
48	+
49	+describe('Notation formatting in celestial descriptions', () => {
50	+  test('Effarig effects() applies formatInt to glyphLevelCap', async () => {
51	+    // Dynamic import so globals are set up (beforeAll runs first)
52	+    await import('../core/celestials/celestials.js');
53	+
54	+    const descriptions = global.GameDatabase.celestials.descriptions;
55	+    expect(Array.isArray(descriptions), 'descriptions should be an array').toBe(true);
56	+
57	+    const effarig = descriptions.find(d => d.name === 'Effarig');
58	+    expect(effarig, 'Effarig description not found').toBeTruthy();
59	+
60	+    const text = effarig.effects();
61	+    // This assertion FAILS on base (text has "2000" not "[FMT:2000]")
62	+    // and PASSES on fix (formatInt wraps the value -> "[FMT:2000]")
63	+    expect(text, `effects() returned: "${text}"`).toContain('[FMT:2000]');
64	+    // Proves the call site actually invoked formatInt with the real glyph
65	+    // level cap value, rather than the text merely happening to match.
66	+    expect(global.formatInt, 'formatInt was never called').toHaveBeenCalledWith(2000);
67	+
68	+    // Re-read effects() after the underlying value changes. A fix that
69	+    // hardcodes formatInt(2000) (copying the mocked value instead of
70	+    // referencing Effarig.glyphLevelCap) passes every assertion above but
71	+    // fails this one, because the text would still say 2000.
72	+    MockEffarig.glyphLevelCap = 733;
73	+    global.formatInt.mockClear();
74	+    const text2 = effarig.effects();
75	+    expect(text2, `effects() returned after glyphLevelCap changed: "${text2}"`)
76	+      .toContain('[FMT:733]');
77	+    expect(text2, 'stale value 2000 should not remain after glyphLevelCap changed')
78	+      .not.toContain('2000');
79	+    expect(global.formatInt).toHaveBeenCalledWith(733);
80	+
81	+    // Zero is a classic falsy-guard trap: a fix written as
82	+    // `${Effarig.glyphLevelCap && formatInt(...)}` or `${value ? formatInt(value) : value}`
83	+    // passes the two checks above (both values are truthy) but silently stops
84	+    // formatting the moment the cap is 0.
85	+    MockEffarig.glyphLevelCap = 0;
86	+    global.formatInt.mockClear();
87	+    const text3 = effarig.effects();
88	+    expect(text3, `effects() returned after glyphLevelCap set to 0: "${text3}"`)
89	+      .toContain('[FMT:0]');
90	+    expect(global.formatInt, 'formatInt must still be called when the value is 0')
91	+      .toHaveBeenCalledWith(0);
92	+  });
93	+});
94	+
95	+// ---------------------------------------------------------------------------
96	+// PelleTab tests mount the component's OWN <script> and <template> exactly as
97	+// shipped, instead of a hand-written stand-in for its data/computed/methods.
98	+// That way a fix is free to restructure the component (e.g. move the "17"
99	+// threshold behind a computed property instead of repeating it) as long as
100	+// the rendered output is correct - only the observable text and the formatInt
101	+// spy are asserted on, never the component's internal shape.
102	+// ---------------------------------------------------------------------------
103	+
104	+function extractComponentOptions(source) {
105	+  const scriptMatch = source.match(/<script>([\s\S]*?)<\/script>/);
106	+  expect(scriptMatch, 'Could not find <script> block in PelleTab.vue').toBeTruthy();
107	+  let scriptSrc = scriptMatch[1];
108	+
109	+  // The rendered branch under test never touches a child component, so each
110	+  // import only needs to exist as an identifier, not resolve to anything real.
111	+  const importNames = [];
112	+  const importRe = /import\s+(?:\{([^}]+)\}|(\w+))\s+from\s+["'][^"']+["'];?/g;
113	+  let m;
114	+  while ((m = importRe.exec(scriptSrc))) {
115	+    if (m[1]) m[1].split(',').forEach(n => importNames.push(n.trim().split(/\s+as\s+/).pop()));
116	+    if (m[2]) importNames.push(m[2]);
117	+  }
118	+  scriptSrc = scriptSrc.replace(importRe, '')
119	+    .replace(/export\s+default\s+/, '')
120	+    .trim()
121	+    .replace(/;\s*$/, '');
122	+
123	+  const decls = importNames.map(n => `const ${n} = {};`).join('\n');
124	+  // eslint-disable-next-line no-new-func
125	+  const factory = new Function(`${decls}\nreturn (${scriptSrc});`);
126	+  return factory();
127	+}
128	+
129	+function renderPanel(completedRows) {
130	+  const filePath = path.resolve(__dirname, '../../src/components/tabs/celestial-pelle/PelleTab.vue');
131	+  const source = fs.readFileSync(filePath, 'utf-8');
132	+  const templateMatch = source.match(/<template>([\s\S]*)<\/template>/);
133	+  expect(templateMatch, 'Could not find <template> block in PelleTab.vue').toBeTruthy();
134	+
135	+  const { render, staticRenderFns } = compileToFunctions(templateMatch[1]);
136	+  const componentOptions = extractComponentOptions(source);
137	+
138	+  // Render the "not yet unlocked" branch: isDoomed and canEnterPelle both
139	+  // false, which is already what the component's own data() defaults to.
140	+  return new Vue({
141	+    ...componentOptions,
142	+    render,
143	+    staticRenderFns,
144	+    data() {
145	+      const base = componentOptions.data ? componentOptions.data.call(this) : {};
146	+      return { ...base, completedRows };
147	+    },
148	+    methods: {
149	+      // The real app exposes this via a global Vue.mixin (javascripts/core/app/ui.js);
150	+      // provide it directly here since that mixin isn't installed in this unit test.
151	+      ...(componentOptions.methods || {}),
152	+      formatInt: value => global.formatInt(value),
153	+    },
154	+  }).$mount();
155	+}
156	+
157	+describe('Notation formatting in Pelle unlock requirements', () => {
158	+  test('PelleTab unlock-requirements panel formats the row counts', () => {
159	+    const vm = renderPanel(5);
160	+    const text = vm.$el.textContent;
161	+
162	+    // The panel shows the "17 rows required" threshold twice and the player's
163	+    // current count once. All three numbers should go through formatInt.
164	+    // Base (unfixed): raw "17"/"5" in the text -> no "[FMT:" markers appear.
165	+    // Fix: every number wrapped in formatInt(...) -> two "[FMT:17]" and one "[FMT:5]".
166	+    const requiredCount = (text.match(/\[FMT:17\]/g) || []).length;
167	+    expect(requiredCount, `expected both "17" thresholds formatted, got text: "${text}"`).toBe(2);
168	+    expect(text, `expected completedRows formatted, got text: "${text}"`).toContain('[FMT:5]');
169	+
170	+    // Proves both values are genuine formatInt(...) calls, not hand-tagged
171	+    // literals sitting in the template with the right shape: a hardcoded
172	+    // "[FMT:17]"/"[FMT:5]" would match the text above but never call the spy.
173	+    // (Not asserting an exact call COUNT: a fix may cache the "17" behind a
174	+    // computed property and legitimately call formatInt with it only once
175	+    // even though it appears twice in the rendered text.)
176	+    expect(global.formatInt, 'formatInt was never called with 17').toHaveBeenCalledWith(17);
177	+    expect(global.formatInt, 'formatInt was never called with 5').toHaveBeenCalledWith(5);
178	+
179	+    // Boundary case: completedRows equal to the 17-row threshold. A fix that only
180	+    // formats completedRows while it is still "less than 17" (e.g. a v-if branch
181	+    // that swaps in a raw, unformatted count once the requirement is met) would
182	+    // pass every check above but fail here.
183	+    global.formatInt.mockClear();
184	+    const vmEqual = renderPanel(17);
185	+    const textEqual = vmEqual.$el.textContent;
186	+    const equalCount = (textEqual.match(/\[FMT:17\]/g) || []).length;
187	+    expect(equalCount, `expected all three "17"s formatted when completedRows===17, got: "${textEqual}"`)
188	+      .toBe(3);
189	+    expect(global.formatInt, 'formatInt was never called at the completedRows===17 boundary')
190	+      .toHaveBeenCalledWith(17);
191	+  });
192	+
193	+  test('PelleTab completedRows binding tracks the real prop, not a hardcoded copy', () => {
194	+    // A fix that hardcodes formatInt(5) (copying the value used in the sibling
195	+    // test) instead of binding {{ formatInt(completedRows) }} would pass the
196	+    // test above unnoticed. Re-rendering with a different completedRows value
197	+    // catches exactly that shortcut.
198	+    global.formatInt.mockClear();
199	+    const vm = renderPanel(0);
200	+    const text = vm.$el.textContent;
201	+
202	+    expect(text, `expected completedRows=0 formatted, got text: "${text}"`).toContain('[FMT:0]');
203	+    expect(text, 'stale value 5 should not remain when completedRows is 0')
204	+      .not.toContain('[FMT:5]');
205	+    expect(global.formatInt).toHaveBeenCalledWith(0);
206	+
207	+    // A fix that special-cases exactly the two values exercised so far (5 and 0)
208	+    // — e.g. a lookup table instead of a real binding — would still pass both
209	+    // checks above. A third, arbitrary value that neither test chose rules
210	+    // that out.
211	+    global.formatInt.mockClear();
212	+    const vmArbitrary = renderPanel(42);
213	+    const textArbitrary = vmArbitrary.$el.textContent;
214	+    expect(textArbitrary, `expected completedRows=42 formatted, got text: "${textArbitrary}"`)
215	+      .toContain('[FMT:42]');
216	+    expect(textArbitrary, 'stale value 0 should not remain when completedRows is 42')
217	+      .not.toContain('[FMT:0]');
218	+    expect(global.formatInt).toHaveBeenCalledWith(42);
219	+  });
220	+});
